using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns an HTTPS or a tg: link with the given type. Can be called before authorization
    /// </summary>
    public Task<TdLib.TdApi.Objects.HttpUrl> GetInternalLinkAsync(InternalLinkType type = default, bool isHttp = default)
    {

           using var activity =  StartCallActivity("GetInternalLinkAsync", typeof(GetInternalLink).FullName ?? "GetInternalLinkAsync");

           try
           {
             return client.GetInternalLinkAsync(type, isHttp);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
